445			found := false
446			for _, p := range m.Projects {
447				if strings.EqualFold(projectName, p.Name) {
448					ids = append(ids, p.ID)
449					found = true
450					break
451				}
452			}
453			if !found {
454				return nil, fmt.Errorf("'%s' not found", projectName)
455			}
456		}
457		return ids, nil
458	}
